<?php require_once __DIR__.'/config/functions.php';
$perPage=8;$page=max(1,(int)($_GET['page']??1));$offset=($page-1)*$perPage;$catSlug=trim($_GET['category']??'');
$where="b.status='published' AND b.publish_date<=NOW()";$params=[];$categoryInfo=null;
if($catSlug){$st=db()->prepare("SELECT * FROM blog_categories WHERE slug=? AND status='active' LIMIT 1");$st->execute([$catSlug]);$categoryInfo=$st->fetch();if($categoryInfo){$where.=' AND b.category_id=?';$params[]=$categoryInfo['id'];}}
$countSt=db()->prepare("SELECT COUNT(*) FROM blogs b WHERE $where");$countSt->execute($params);$total=(int)$countSt->fetchColumn();$pages=max(1,(int)ceil($total/$perPage));
$sql="SELECT b.*,c.name category_name,c.slug category_slug FROM blogs b JOIN blog_categories c ON c.id=b.category_id WHERE $where ORDER BY b.publish_date DESC,b.id DESC LIMIT $perPage OFFSET $offset";$st=db()->prepare($sql);$st->execute($params);$blogs=$st->fetchAll();$cats=db()->query("SELECT c.*,COUNT(b.id) total FROM blog_categories c LEFT JOIN blogs b ON b.category_id=c.id AND b.status='published' AND b.publish_date<=NOW() WHERE c.status='active' GROUP BY c.id ORDER BY c.name")->fetchAll();
$title=$categoryInfo ? $categoryInfo['name'].' | Editorials' : 'Editorials';$meta=$categoryInfo ? 'Read the latest '.$categoryInfo['name'].' stories and editorial updates from VBCCS.' : 'Read the latest editorial stories, community updates, culture, education and wellness insights from VBCCS.';
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?> | VBCCS</title><meta name="description" content="<?=e($meta)?>"><link rel="icon" href="assets/images/favicon.png"><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.8/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.7.2/css/all.min.css" rel="stylesheet"><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="css/style.css"><link rel="stylesheet" href="css/blog.css"></head><body><?php include __DIR__.'/include/header.php'; ?><main class="blog-page"><section class="blog-hero"><div class="container"><span class="blog-kicker">VBCCS EDITORIAL</span><h1><?=e($categoryInfo ? $categoryInfo['name'] : 'Editorials')?></h1><p>Stories, ideas and updates from our community.</p></div></section><section class="blog-listing-section"><div class="container"><div class="row g-5"><div class="col-lg-8"><div class="editorial-list"><?php foreach($blogs as $b): ?><article class="editorial-item"><div class="editorial-meta"><span><?=strtoupper(date('M d, Y',strtotime($b['publish_date'])))?></span></div><div class="editorial-copy"><a class="category-label" href="editorial.php?category=<?=urlencode($b['category_slug'])?>"><?=e($b['category_name'])?></a><h2><a href="blog-detail.php?slug=<?=urlencode($b['slug'])?>"><?=e($b['title'])?></a></h2><div class="editorial-author"><?=e($b['author'])?></div><p><?=e($b['short_description'])?></p><div class="read-time"><?=e($b['read_time'] ?: '5 min read')?></div></div><a class="editorial-image" href="blog-detail.php?slug=<?=urlencode($b['slug'])?>"><img src="<?=e($b['featured_image'] ?: 'assets/logo.png')?>" alt="<?=e($b['title'])?>" loading="lazy"></a></article><?php endforeach; if(!$blogs): ?><div class="empty-blog">No published blogs found in this category yet.</div><?php endif;?></div><?php if($pages>1): ?><nav class="blog-pagination"><ul><?php for($i=1;$i<=$pages;$i++): ?><li class="<?=$i===$page?'active':''?>"><a href="?<?=http_build_query(array_filter(['page'=>$i,'category'=>$catSlug]))?>"><?=$i?></a></li><?php endfor;?></ul></nav><?php endif;?></div><aside class="col-lg-4"><div class="blog-sidebar"><div class="sidebar-widget"><h3>Recent Editorials</h3><?php foreach(published_blogs(5) as $r): ?><a class="recent-post" href="blog-detail.php?slug=<?=urlencode($r['slug'])?>"><strong><?=e($r['title'])?></strong><span><?=e($r['short_description'])?></span></a><?php endforeach;?></div><div class="sidebar-widget"><h3>Blog Categories</h3><div class="category-list"><?php foreach($cats as $c): ?><a href="editorial.php?category=<?=urlencode($c['slug'])?>"><?=e($c['name'])?><span><?=$c['total']?></span></a><?php endforeach;?></div></div><div class="sidebar-widget subscribe-widget"><h3>Subscribe to Our Editorial</h3><p>Stay connected with the latest community stories and updates.</p><form onsubmit="return false"><input type="email" placeholder="Enter your email"><button>Sign Up</button></form></div></div></aside></div></div></section></main><?php include __DIR__.'/include/footer.php'; ?></body></html>
